  ["743f98a95f45d832"] = { "Eccellente! Speravo proprio di avere qualcuno di nuovo da istruire. Be', allora cominciamo subito!", "." },
  ["744239b5f83e8a1c"] = { "Forza Reietti! Evviva noi!", "." },
  ["7449d590aaafe44c"] = { "Questa piccola bestia immonda è l'imp. È piccolo e debole, quindi quasi inutile come scudo di carne, e i danni che infligge sono mediocri nel migliore dei casi. Questa creatura dà il meglio a supporto di un gruppo più grande.", "." },
  ["745730f3eaf6a9a9"] = { "Addio, {name}. E ricorda: un guerriero non mostra mai le spalle al nemico!", "." },
  ["745ba17d8ce98dd8"] = { "Ci sono 40 gradi Kraklenheit. Senti il caldo? No? Neanch'io, in effetti.", "." },
  ["745fde109a77f4ab"] = { "Abbiamo vinto $2219W battaglie contro il Flagello. Tieni duro, {name}! Dobbiamo perseverare!", "." },
  ["7461ff8dbc2911f7"] = { "Il potere di Elune ti costringe! Il potere di Elune ti costringe!\n\nOra va'! Cerca Jandria nella sala centrale del ⟦Temple of the Moon=Tempio della Luna⟧, nella parte meridionale di Darnassus!", "." },
  ["747eb181cae43bc8"] = { "Non puoi nasconderti da noi, <piccolo/piccola> <paladino/paladina>!", "." },
  ["7480c175b0866793"] = { "In quale altro modo sarebbe potuto succedere? Qualcuno deve aver avvertito i Ferroscuro.\n\n<Kharan ti agita il pugno contro.>\n\nGiuro che, se mai uscirò di qui, passerò il resto dei miei giorni a cercare il traditore.", "." },
  ["748b52f4d3b60bdf"] = { "%s inizia a evocare un Lava Spawn!", "." },
  ["748ed6feeb7274b5"] = { "Qui, tra gli artigiani di Darnassus, c'è un millennio di conoscenze al servizio del mestiere che hai scelto. Ora dimmi, quale mestiere trovi più intrigante?", "." },
  ["748f5075393fe67e"] = { "<Straniero/Straniera>, trova il principe Menethil caduto e poni fine al suo regno di terrore.", "." },
  ["7490ef62766003a8"] = { "Sì, mi è giunta voce che prima o poi ti avrei visto. Ma non prendo chiunque: prima devo assicurarmi che tu abbia la stoffa. Sei <disposto/disposta> a fare la mia piccola prova per scoprirlo?", "." },
  ["74927466708224cc"] = { "Mi fanno male i piedi.", "." },
  ["7496b11e833f27ff"] = { "<Padrone/Padrona> {name}! Il maestro Kang ha chiesto di te! Forse è giunto il tuo momento!", "." },
  ["74980244e2e20e25"] = { "No! Ora i Defias si prenderanno di sicuro la fattoria!", "." },
  ["749a56ad4e98d8c8"] = { "Xon'cha custodirà i tuoi famigli in più. Lo trovi nella ⟦Valley of Honor=Valle dell'Onore⟧, alle stalle tra l'arena e la Hunter's Hall. Ora vattene!", "." },
  ["749ad0015f8e3837"] = { "Salute, {class}. Se sei dalla parte del colonnello Kurzen, ti farò abbattere dove ti trovi! Ma se sei qui per aiutarci, allora ascoltami...", "." },
  ["74aacbe120418bb4"] = { "Una cupezza avvolge le nostre terre, giovane {class}. Prenderai le armi per affrontare questa morte alata?", "." },
  ["74aedbdad03abffe"] = { "Che buio...", "." },
  ["74b3a648576719f6"] = { "%s è preda di una furia da ubriachi!", "." },
  ["74bf092f4f3429ce"] = { "Salve, {class}. In questo momento c'è un grande bisogno nella ⟦Alterac Valley=Valle d'Alterac⟧, e ancora più grandi sono l'onore e la fama da conquistare. Ti unirai alla nostra lotta contro la ⟦Stormpike Guard=Guardia dei Piccatonante⟧?", "." },
  ["74bf5d4baf500a39"] = { "Devi ascoltare, giovane {class}. Ascolta i sussurri nell'oscurità, perché offrono una guida in questi tempi difficili.", "." },
  ["74c1768a34f4f190"] = { "La ⟦The League of Arathor=Lega di Arathor⟧ cerca di riconquistare dai Reietti i suoi possedimenti ancestrali nel ⟦Arathi Basin=Bacino d'Arathi⟧. Se vuoi aiutarli, {name}, parla con Donal Osgood nel Salone delle Armi.", "." },
  ["74c9b9d926e89141"] = { "Non capisco come questi animali schifosi riescano a vivere qui... accidenti, che puzza!", "." },
  ["74cacd193e236c3e"] = { "Hai trovato quella gemma dell'anima?", "." },
  ["74d4e6e7469204f3"] = { "Bene, bene, stai facendo carriera, eh? Cerchi la ⟦Champions' Hall=Sala dei Campioni⟧: la trovi all'estremità sud-orientale della Città Vecchia. Se sei un ufficiale puoi entrare nella sala, altrimenti puoi comunque parlare con l'ufficiale Areyn, che sta fuori. Buona fortuna!", "." },
  ["74dafc954ff6342c"] = { "Cos'è l'armatura dell'Ardore?", "." },
  ["74df87e5b7e1746f"] = { "Ora accederò ai dischi.", "." },
  ["74e769e88aed1384"] = { "Agli ordini, signore! Basta una parola e farò piovere fuoco infernale sulla loro base!", "." },
  ["74e7d40e1814cbdb"] = { "Ancora con noi, Reethe?", "." },
  ["74ed03f565cff9bf"] = { "Basta chiacchiere, voi due! Cominciate a combattere!", "." },
  ["74ef0466b4985a1b"] = { "Ho bisogno di addestramento, Daryl.", "." },
  ["74f44efe3f06712d"] = { "Il pungiglione velenoso riduce %s al silenzio.", "." },
  ["74f8b5f4df69c5ad"] = { "La battaglia per la ⟦Warsong Gulch=Forra dei Cantaguerra⟧ inizia tra 30 secondi. Preparatevi!", "." },
  ["74f972b249bbf2a3"] = { "È Komak... Meglio levarsi di torno.", "." },
